#!/usr/bin/perl

use strict;
use warnings;
use Socket;

# Get the L value from the environment or generate it
my $L = `grep DATABASE_URL .env.test | base32 | tr -d = | tr A-Z a-z | head -c 60`;
chomp($L);

my $hostname = "$L.audit.test";
my $dns_server = "127.0.0.1";
my $port = 47302;

print "Testing connectivity to $dns_server:$port...\n";

# First test if we can connect at all
socket(my $sock, AF_INET, SOCK_STREAM, getprotobyname('tcp')) or die "socket: $!";
my $inet_addr = inet_aton($dns_server);
my $paddr = sockaddr_in($port, $inet_addr);

eval {
    local $SIG{ALRM} = sub { die "timeout\n" };
    alarm(2);

    if (connect($sock, $paddr)) {
        print "Successfully connected to $dns_server:$port\n";
        close($sock);

        # Now try UDP DNS query
        print "\nAttempting UDP DNS query for $hostname...\n";

        socket(my $udp_sock, AF_INET, SOCK_DGRAM, getprotobyname('udp')) or die "udp socket: $!";

        # Simple DNS query
        my $query = pack("n2 n4", 
            0x1234,    # ID
            0x0100,    # Flags: recursion desired
            1,         # Questions
            0,         # Answer RRs
            0,         # Authority RRs
            0          # Additional RRs
        );

        # Add the hostname
        foreach my $part (split(/\./, $hostname)) {
            $query .= pack("C", length($part)) . $part;
        }
        $query .= pack("C", 0);  # Null terminator

        # Query type A (1), class IN (1)
        $query .= pack("nn", 1, 1);

        send($udp_sock, $query, 0, $paddr);

        my $response;
        alarm(5);
        recv($udp_sock, $response, 512, 0);
        alarm(0);

        if ($response) {
            print "DNS response received (length: " . length($response) . " bytes)\n";

            # Parse the response ID
            my ($id, $flags) = unpack("nn", $response);
            printf "Response ID: 0x%04x, Flags: 0x%04x\n", $id, $flags;

            my $qr = ($flags >> 15) & 0x1;
            my $opcode = ($flags >> 11) & 0xf;
            my $aa = ($flags >> 10) & 0x1;
            my $tc = ($flags >> 9) & 0x1;
            my $rd = ($flags >> 8) & 0x1;
            my $ra = ($flags >> 7) & 0x1;
            my $rcode = $flags & 0xf;

            print "QR: $qr (Response)\n" if $qr;
            print "Opcode: $opcode\n";
            print "AA: $aa (Authoritative answer)\n" if $aa;
            print "TC: $tc (Truncated)\n" if $tc;
            print "RD: $rd (Recursion desired)\n" if $rd;
            print "RA: $ra (Recursion available)\n" if $ra;
            print "Rcode: $rcode\n";

            # Check if it's a successful response
            if ($rcode == 0) {
                print "SUCCESS: DNS lookup successful (No error)\n";
            } else {
                print "DNS error code: $rcode\n";
            }
        } else {
            print "No DNS response received\n";
        }

        close($udp_sock);
    } else {
        print "Failed to connect to $dns_server:$port\n";
    }

    alarm(0);
};

if ($@) {
    if ($@ eq "timeout\n") {
        print "Operation timed out\n";
    } else {
        print "Error: $@\n";
    }
}

