const authorityRRs = 0;
const additionalRRs = 0;

// Build DNS query
const buf = Buffer.alloc(512);
let offset = 0;

// Header
buf.writeUInt16BE(queryId, offset); offset += 2;
buf.writeUInt16BE(flags, offset); offset += 2;
buf.writeUInt16BE(questions, offset); offset += 2;
buf.writeUInt16BE(answerRRs, offset); offset += 2;
buf.writeUInt16BE(authorityRRs, offset); offset += 2;
buf.writeUInt16BE(additionalRRs, offset); offset += 2;

// Question: domain
