for (const label of labels) {
  buf.writeUInt8(label.length, offset); offset += 1;
  buf.write(label, offset); offset += label.length;
}
buf.writeUInt8(0, offset); offset += 1; // null terminator

// Question type (A record) and class (IN)
buf.writeUInt16BE(1, offset); offset += 2; // Type A
buf.writeUInt16BE(1, offset); offset += 2; // Class IN

const message = buf.slice(0, offset);

// Send DNS query
const client = dgram.createSocket('udp4');
const port = 47302;
const host = 'localhost';

client.send(message, port, host, (err) => {
